PRAGMA foreign_keys = ON;
CREATE TABLE users(id INTEGER PRIMARY KEY,display_name TEXT NOT NULL,email TEXT NOT NULL COLLATE NOCASE UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('buyer','artist','admin')),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')),bio TEXT NOT NULL DEFAULT '',region TEXT NOT NULL DEFAULT '',avatar_media_id INTEGER REFERENCES media(id),status_reason TEXT,status_changed_by INTEGER REFERENCES users(id),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE artist_profiles(user_id INTEGER PRIMARY KEY REFERENCES users(id),specialties TEXT NOT NULL DEFAULT '',experience_summary TEXT NOT NULL DEFAULT '',badge TEXT NOT NULL DEFAULT 'sibol' CHECK(badge IN ('sibol','dalubhasa')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE media(id INTEGER PRIMARY KEY,owner_id INTEGER NOT NULL REFERENCES users(id),storage_path TEXT NOT NULL UNIQUE,original_name TEXT NOT NULL,mime_type TEXT NOT NULL,byte_size INTEGER NOT NULL,width INTEGER NOT NULL,height INTEGER NOT NULL,alt_text TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE artworks(id INTEGER PRIMARY KEY,artist_id INTEGER NOT NULL REFERENCES artist_profiles(user_id),title TEXT NOT NULL,description TEXT NOT NULL,medium TEXT NOT NULL,width_mm INTEGER,height_mm INTEGER,year_created INTEGER,region TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'visible' CHECK(status IN ('visible','archived','hidden')),sold_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE badge_reviews(id INTEGER PRIMARY KEY,artist_id INTEGER NOT NULL REFERENCES artist_profiles(user_id),kind TEXT NOT NULL DEFAULT 'application',statement TEXT NOT NULL,evidence_artwork_id INTEGER REFERENCES artworks(id),status TEXT NOT NULL DEFAULT 'pending',reviewed_by INTEGER REFERENCES users(id),decision_reason TEXT,created_at TEXT NOT NULL,reviewed_at TEXT);
CREATE UNIQUE INDEX one_pending_badge ON badge_reviews(artist_id) WHERE status='pending';
CREATE TABLE artwork_images(artwork_id INTEGER NOT NULL REFERENCES artworks(id),media_id INTEGER NOT NULL REFERENCES media(id),sort_order INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(artwork_id,media_id),UNIQUE(artwork_id,sort_order));
CREATE TABLE listings(id INTEGER PRIMARY KEY,seller_id INTEGER NOT NULL REFERENCES artist_profiles(user_id),artwork_id INTEGER REFERENCES artworks(id),section TEXT NOT NULL CHECK(section IN ('subasta','likha_lokal','arkilikha','gawang_hiling','kagamit','museo')),category TEXT NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL,unit_price_centavos INTEGER NOT NULL CHECK(unit_price_centavos>0),stock_qty INTEGER NOT NULL CHECK(stock_qty>=0),condition_notes TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'published' CHECK(status IN ('draft','published','paused','sold_out','archived','hidden')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX one_active_original ON listings(artwork_id) WHERE artwork_id IS NOT NULL AND status IN ('published','paused');
CREATE TRIGGER original_owner BEFORE INSERT ON listings WHEN NEW.artwork_id IS NOT NULL BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM artworks WHERE id=NEW.artwork_id AND artist_id=NEW.seller_id AND sold_at IS NULL AND status='visible') OR NEW.stock_qty<>1 THEN RAISE(ABORT,'Artwork is not available or not yours') END; END;
CREATE TABLE listing_images(listing_id INTEGER NOT NULL REFERENCES listings(id),media_id INTEGER NOT NULL REFERENCES media(id),sort_order INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(listing_id,media_id),UNIQUE(listing_id,sort_order));
CREATE TABLE auctions(id INTEGER PRIMARY KEY,listing_id INTEGER NOT NULL UNIQUE REFERENCES listings(id),starts_at TEXT NOT NULL,ends_at TEXT NOT NULL CHECK(ends_at>starts_at),min_increment_centavos INTEGER NOT NULL CHECK(min_increment_centavos>0),status TEXT NOT NULL DEFAULT 'live',winning_bid_id INTEGER UNIQUE REFERENCES bids(id),finalized_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE bids(id INTEGER PRIMARY KEY,auction_id INTEGER NOT NULL REFERENCES auctions(id),bidder_id INTEGER NOT NULL REFERENCES users(id),amount_centavos INTEGER NOT NULL CHECK(amount_centavos>0),request_token TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL);
CREATE TRIGGER matching_winner BEFORE UPDATE OF winning_bid_id ON auctions WHEN NEW.winning_bid_id IS NOT NULL BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM bids WHERE id=NEW.winning_bid_id AND auction_id=NEW.id) THEN RAISE(ABORT,'Winner is from another auction') END; END;
CREATE TABLE rental_rate_tiers(id INTEGER PRIMARY KEY,label TEXT NOT NULL,min_days INTEGER NOT NULL,max_days INTEGER,commission_bps INTEGER NOT NULL CHECK(commission_bps BETWEEN 0 AND 10000),is_active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE rental_bookings(id INTEGER PRIMARY KEY,listing_id INTEGER NOT NULL REFERENCES listings(id),renter_id INTEGER NOT NULL REFERENCES users(id),start_date TEXT NOT NULL,end_date TEXT NOT NULL CHECK(end_date>start_date),days INTEGER NOT NULL CHECK(days BETWEEN 1 AND 30),daily_rate_centavos INTEGER NOT NULL,rate_tier_id INTEGER NOT NULL REFERENCES rental_rate_tiers(id),commission_bps INTEGER NOT NULL,rental_total_centavos INTEGER NOT NULL,platform_fee_centavos INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'requested',hold_expires_at TEXT,decision_note TEXT,collected_at TEXT,returned_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE commission_offers(listing_id INTEGER PRIMARY KEY REFERENCES listings(id),slot_capacity INTEGER NOT NULL CHECK(slot_capacity>0),estimated_days INTEGER NOT NULL CHECK(estimated_days>0),revision_limit INTEGER NOT NULL CHECK(revision_limit>=0),terms TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE commission_requests(id INTEGER PRIMARY KEY,offer_listing_id INTEGER NOT NULL REFERENCES commission_offers(listing_id),buyer_id INTEGER NOT NULL REFERENCES users(id),brief TEXT NOT NULL,budget_centavos INTEGER,requested_due_date TEXT,reference_media_id INTEGER REFERENCES media(id),quoted_price_centavos INTEGER,quoted_due_date TEXT,agreed_revision_limit INTEGER,revisions_used INTEGER NOT NULL DEFAULT 0,quote_expires_at TEXT,checkout_expires_at TEXT,status TEXT NOT NULL DEFAULT 'requested',decision_note TEXT,accepted_at TEXT,completed_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE commission_messages(id INTEGER PRIMARY KEY,request_id INTEGER NOT NULL REFERENCES commission_requests(id),author_id INTEGER NOT NULL REFERENCES users(id),kind TEXT NOT NULL DEFAULT 'note',body TEXT NOT NULL,attachment_media_id INTEGER REFERENCES media(id),created_at TEXT NOT NULL);
CREATE TABLE posts(id INTEGER PRIMARY KEY,author_id INTEGER NOT NULL REFERENCES users(id),shared_post_id INTEGER REFERENCES posts(id),body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'visible',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX one_share ON posts(author_id,shared_post_id) WHERE shared_post_id IS NOT NULL AND status='visible';
CREATE TABLE post_images(post_id INTEGER NOT NULL REFERENCES posts(id),media_id INTEGER NOT NULL REFERENCES media(id),sort_order INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(post_id,media_id),UNIQUE(post_id,sort_order));
CREATE TABLE post_reactions(post_id INTEGER NOT NULL REFERENCES posts(id),user_id INTEGER NOT NULL REFERENCES users(id),reaction TEXT NOT NULL CHECK(reaction IN ('like','love','wow')),created_at TEXT NOT NULL,PRIMARY KEY(post_id,user_id));
CREATE TABLE comments(id INTEGER PRIMARY KEY,post_id INTEGER NOT NULL REFERENCES posts(id),author_id INTEGER NOT NULL REFERENCES users(id),parent_comment_id INTEGER REFERENCES comments(id),body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'visible',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE saved_items(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),listing_id INTEGER REFERENCES listings(id),artwork_id INTEGER REFERENCES artworks(id),post_id INTEGER REFERENCES posts(id),artist_id INTEGER REFERENCES artist_profiles(user_id),created_at TEXT NOT NULL,CHECK((listing_id IS NOT NULL)+(artwork_id IS NOT NULL)+(post_id IS NOT NULL)+(artist_id IS NOT NULL)=1));
CREATE UNIQUE INDEX save_listing ON saved_items(user_id,listing_id) WHERE listing_id IS NOT NULL;
CREATE UNIQUE INDEX save_artwork ON saved_items(user_id,artwork_id) WHERE artwork_id IS NOT NULL;
CREATE UNIQUE INDEX save_post ON saved_items(user_id,post_id) WHERE post_id IS NOT NULL;
CREATE UNIQUE INDEX save_artist ON saved_items(user_id,artist_id) WHERE artist_id IS NOT NULL;
CREATE TABLE cart_items(id INTEGER PRIMARY KEY,buyer_id INTEGER NOT NULL REFERENCES users(id),listing_id INTEGER NOT NULL REFERENCES listings(id),quantity INTEGER NOT NULL CHECK(quantity>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(buyer_id,listing_id));
CREATE TABLE orders(id INTEGER PRIMARY KEY,order_number TEXT NOT NULL UNIQUE,buyer_id INTEGER NOT NULL REFERENCES users(id),source TEXT NOT NULL,recipient_name TEXT NOT NULL,fulfillment_method TEXT NOT NULL DEFAULT 'pickup',pickup_notes TEXT NOT NULL DEFAULT '',total_centavos INTEGER NOT NULL,payment_status TEXT NOT NULL DEFAULT 'awaiting_demo_payment',checkout_token TEXT NOT NULL UNIQUE,payment_due_at TEXT,demo_paid_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE order_items(id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders(id),listing_id INTEGER NOT NULL REFERENCES listings(id),seller_id INTEGER NOT NULL REFERENCES artist_profiles(user_id),auction_id INTEGER UNIQUE REFERENCES auctions(id),rental_booking_id INTEGER UNIQUE REFERENCES rental_bookings(id),commission_request_id INTEGER UNIQUE REFERENCES commission_requests(id),item_title TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),unit_price_centavos INTEGER NOT NULL,line_total_centavos INTEGER NOT NULL,commission_bps INTEGER NOT NULL DEFAULT 0,platform_fee_centavos INTEGER NOT NULL DEFAULT 0,seller_net_centavos INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'confirmed',cancelled_by INTEGER REFERENCES users(id),cancellation_reason TEXT,cancelled_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,CHECK((auction_id IS NOT NULL)+(rental_booking_id IS NOT NULL)+(commission_request_id IS NOT NULL)<=1));
CREATE TABLE notifications(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),message TEXT NOT NULL,target_path TEXT NOT NULL,event_key TEXT NOT NULL UNIQUE,read_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE reports(id INTEGER PRIMARY KEY,reporter_id INTEGER NOT NULL REFERENCES users(id),reported_user_id INTEGER REFERENCES users(id),listing_id INTEGER REFERENCES listings(id),artwork_id INTEGER REFERENCES artworks(id),post_id INTEGER REFERENCES posts(id),comment_id INTEGER REFERENCES comments(id),reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',reviewed_by INTEGER REFERENCES users(id),resolution_note TEXT,created_at TEXT NOT NULL,resolved_at TEXT,CHECK((reported_user_id IS NOT NULL)+(listing_id IS NOT NULL)+(artwork_id IS NOT NULL)+(post_id IS NOT NULL)+(comment_id IS NOT NULL)=1));
CREATE TABLE moderation_actions(id INTEGER PRIMARY KEY,admin_id INTEGER NOT NULL REFERENCES users(id),report_id INTEGER REFERENCES reports(id),target_user_id INTEGER REFERENCES users(id),listing_id INTEGER REFERENCES listings(id),artwork_id INTEGER REFERENCES artworks(id),post_id INTEGER REFERENCES posts(id),comment_id INTEGER REFERENCES comments(id),action TEXT NOT NULL,reason TEXT NOT NULL,previous_status TEXT NOT NULL,new_status TEXT NOT NULL,created_at TEXT NOT NULL,CHECK((target_user_id IS NOT NULL)+(listing_id IS NOT NULL)+(artwork_id IS NOT NULL)+(post_id IS NOT NULL)+(comment_id IS NOT NULL)=1));
CREATE INDEX listing_section ON listings(section,status);
CREATE INDEX artwork_artist ON artworks(artist_id,status);
CREATE INDEX auction_end ON auctions(status,ends_at);
CREATE INDEX bid_amount ON bids(auction_id,amount_centavos DESC,id);
CREATE INDEX rental_dates ON rental_bookings(listing_id,status,start_date,end_date);
CREATE INDEX commission_status ON commission_requests(offer_listing_id,status);
CREATE INDEX feed_time ON posts(status,created_at DESC,id DESC);
CREATE INDEX comment_post ON comments(post_id,status);
CREATE INDEX order_buyer ON orders(buyer_id,created_at DESC);
CREATE INDEX item_seller ON order_items(seller_id,status);
CREATE INDEX notice_user ON notifications(user_id,read_at);
